#!/usr/bin/env node
/**
 * AAWP Address Book — name → address mappings
 * Storage: ~/.aawp-address-book.json
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { ethers } = require('ethers');

const BOOK_PATH = path.join(process.env.HOME || '/root', '.aawp-address-book.json');

function load() {
  try { return JSON.parse(fs.readFileSync(BOOK_PATH, 'utf8')); }
  catch { return {}; }
}

function save(book) {
  fs.writeFileSync(BOOK_PATH, JSON.stringify(book, null, 2));
}

function add(name, address) {
  if (!ethers.isAddress(address)) throw new Error(`Invalid address: ${address}`);
  const book = load();
  book[name.toLowerCase()] = ethers.getAddress(address);
  save(book);
  return book[name.toLowerCase()];
}

function get(name) {
  const book = load();
  return book[name.toLowerCase()] || null;
}

function list() {
  return load();
}

function remove(name) {
  const book = load();
  const key = name.toLowerCase();
  if (!book[key]) return false;
  delete book[key];
  save(book);
  return true;
}

/**
 * resolve — if it looks like an address (0x..., 42 chars), return as-is.
 * Otherwise look up in address book. Returns address or throws.
 */
function resolve(nameOrAddress) {
  if (!nameOrAddress) throw new Error('Empty address/name');
  if (nameOrAddress.startsWith('0x') && nameOrAddress.length === 42) {
    return nameOrAddress;
  }
  const addr = get(nameOrAddress);
  if (addr) return addr;
  throw new Error(`"${nameOrAddress}" is not a valid address and not found in address book. Use: addr add <name> <address>`);
}

module.exports = { add, get, list, remove, resolve };

'use strict';

const { ethers } = require('ethers');

// Legacy chains that don't support EIP-1559
const LEGACY_CHAINS = ['bsc'];

/**
 * Get dynamic gas price for a chain.
 * EIP-1559 chains: maxFeePerGas = baseFee * 1.5 + maxPriorityFeePerGas
 * Legacy chains (BSC): gasPrice * 1.1
 * @returns {{ maxFeePerGas, maxPriorityFeePerGas } | { gasPrice }}
 */
async function getGasPrice(provider, chainKey) {
  const feeData = await provider.getFeeData();

  if (LEGACY_CHAINS.includes(chainKey) || !feeData.maxFeePerGas) {
    // Legacy pricing
    const base = feeData.gasPrice || 3000000000n;
    const gasPrice = (base * 110n) / 100n; // +10%
    return { gasPrice };
  }

  // EIP-1559
  const baseFee = feeData.maxFeePerGas - (feeData.maxPriorityFeePerGas || 0n);
  const maxPriorityFeePerGas = feeData.maxPriorityFeePerGas || ethers.parseUnits('1', 'gwei');
  const maxFeePerGas = (baseFee * 150n) / 100n + maxPriorityFeePerGas;

  return { maxFeePerGas, maxPriorityFeePerGas };
}

/**
 * Estimate gas cost in native currency (ETH/BNB/MATIC).
 * @param {object} provider
 * @param {object} txParams - { to, value, data }
 * @param {string} chainKey
 * @returns {{ gasLimit: bigint, gasCostWei: bigint, gasCostEth: string }}
 */
async function estimateGasCost(provider, txParams, chainKey) {
  const gasLimit = await provider.estimateGas(txParams).catch(() => 200000n);
  const prices = await getGasPrice(provider, chainKey);
  const effectivePrice = prices.gasPrice || prices.maxFeePerGas;
  const gasCostWei = BigInt(gasLimit) * effectivePrice;

  return {
    gasLimit,
    gasCostWei,
    gasCostEth: ethers.formatEther(gasCostWei),
  };
}

module.exports = { getGasPrice, estimateGasCost };

'use strict';

const { ethers } = require('ethers');
const fs = require('fs');
const path = require('path');

// Multicall3 is deployed at the same address on all EVM chains
const MULTICALL3_ADDR = '0xcA11bde05977b3631167028862bE2a173976CA11';

const MULTICALL3_ABI = [
  'function aggregate3((address target, bool allowFailure, bytes callData)[] calls) payable returns ((bool success, bytes returnData)[])',
];

/**
 * Batch multiple calls into a single wallet execute() via Multicall3.aggregate3.
 * @param {Array} calls - [{ to, value, data, description }]
 * @param {string} walletAddr - AAWP wallet address
 * @param {object} chain - chain config from CHAINS
 * @param {Function} socketQuery - the socketQuery function for signing
 * @param {Function} getNonce - async function returning next nonce
 * @returns {string} txHash
 */
async function batchExecute(calls, walletAddr, chain, socketQuery, getNonce) {
  if (!calls || calls.length === 0) throw new Error('No calls to batch');

  // If only one call has value > 0, we need to sum total value
  const totalValue = calls.reduce((sum, c) => sum + BigInt(c.value || '0'), 0n);

  // Encode Multicall3.aggregate3
  const iface = new ethers.Interface(MULTICALL3_ABI);
  const multicallArgs = calls.map(c => ({
    target: c.to,
    allowFailure: false,
    callData: c.data || '0x',
  }));
  const data = iface.encodeFunctionData('aggregate3', [multicallArgs]);

  const nonce = await getNonce();
  const deadline = Math.floor(Date.now() / 1000) + 3600;

  console.log(`\n📦 Batch executing ${calls.length} calls via Multicall3`);
  for (let i = 0; i < calls.length; i++) {
    console.log(`  ${i + 1}. ${calls[i].description || calls[i].to} (value: ${calls[i].value || '0'})`);
  }

  // Inject guardian private key as gas_key (same logic as sign-worker.js)
  let gasKey;
  try {
    const gPath = path.join(process.env.AAWP_SKILL || '/root/clawd/skills/aawp', 'config/guardian.json');
    const g = JSON.parse(fs.readFileSync(gPath, 'utf8'));
    if (g.privateKey) gasKey = g.privateKey.replace(/^0x/, '');
  } catch (_) {}
  gasKey = process.env.AAWP_GUARDIAN_KEY || process.env.AAWP_GAS_KEY || gasKey;

  const result = await socketQuery({
    cmd: 'sign',
    wallet: walletAddr,
    to: MULTICALL3_ADDR,
    value: '0x' + totalValue.toString(16),
    nonce: Number(nonce),
    deadline,
    chain_id: chain.chainId,
    rpc: chain.rpcOverride || chain.rpc,
    data,
    gas_key: gasKey,
  });

  if (result.error) throw new Error(`Batch sign failed: ${result.error}`);
  return result.result;
}

module.exports = { batchExecute, MULTICALL3_ADDR };

'use strict';

/**
 * NonceManager — local pending nonce tracking to prevent concurrent tx nonce conflicts.
 * Singleton module.
 */
class NonceManager {
  constructor() {
    this._pending = {};  // key: "chainId:walletAddr" → { base, offset }
    this._locks = {};    // simple mutex per key
  }

  _key(walletAddr, chainId) {
    return `${chainId}:${walletAddr.toLowerCase()}`;
  }

  /**
   * Get next nonce (on-chain nonce + local pending offset).
   * @param {object} provider - ethers JsonRpcProvider
   * @param {string} walletAddr - AAWP wallet address
   * @param {number} chainId
   * @param {object} walletContract - ethers Contract with nonce() method
   * @returns {Promise<number>}
   */
  async getNonce(provider, walletAddr, chainId, walletContract) {
    const k = this._key(walletAddr, chainId);

    // Simple lock: wait if another call is in progress
    while (this._locks[k]) {
      await new Promise(r => setTimeout(r, 50));
    }
    this._locks[k] = true;

    try {
      if (!this._pending[k]) {
        // First call: sync from chain
        const onChainNonce = walletContract
          ? Number(await walletContract.nonce())
          : 0;
        this._pending[k] = { base: onChainNonce, offset: 0 };
      }

      const nonce = this._pending[k].base + this._pending[k].offset;
      this._pending[k].offset++;
      return nonce;
    } finally {
      this._locks[k] = false;
    }
  }

  /**
   * Confirm a tx completed (success or failure). Decrements pending offset.
   */
  confirm(walletAddr, chainId) {
    const k = this._key(walletAddr, chainId);
    if (this._pending[k] && this._pending[k].offset > 0) {
      this._pending[k].base++;
      this._pending[k].offset--;
    }
  }

  /**
   * Reset — force re-sync from chain on next getNonce call.
   */
  reset(walletAddr, chainId) {
    const k = this._key(walletAddr, chainId);
    delete this._pending[k];
  }
}

module.exports = new NonceManager();

'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');

const HISTORY_FILE = path.join(os.homedir(), '.aawp-history.json');
const MAX_ENTRIES = 1000;

/**
 * Append a tx entry to history.
 * @param {object} entry - { ts, chain, type, from, to, amount, token, txHash, status, gasUsed }
 */
function append(entry) {
  let history = [];
  try {
    if (fs.existsSync(HISTORY_FILE)) {
      history = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8'));
    }
  } catch { history = []; }

  entry.ts = entry.ts || new Date().toISOString();
  history.push(entry);

  // Keep only last MAX_ENTRIES
  if (history.length > MAX_ENTRIES) {
    history = history.slice(history.length - MAX_ENTRIES);
  }

  fs.writeFileSync(HISTORY_FILE, JSON.stringify(history, null, 2));
}

/**
 * Query tx history with optional filters.
 * @param {object} opts - { chain, limit, type }
 * @returns {Array}
 */
function query({ chain, limit = 20, type } = {}) {
  let history = [];
  try {
    if (fs.existsSync(HISTORY_FILE)) {
      history = JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8'));
    }
  } catch { return []; }

  if (chain) history = history.filter(e => e.chain === chain.toLowerCase());
  if (type) history = history.filter(e => e.type === type.toLowerCase());

  return history.slice(-limit);
}

module.exports = { append, query };

#!/usr/bin/env node
/**
 * AAWP DCA — Dollar Cost Averaging
 * Scheduling: OpenClaw cron (preferred) → system crontab (fallback) → manual
 *
 * Usage:
 *   dca.js add --chain base --from ETH --to USDC --amount 0.01 --cron "0 9 * * *" [--name myDCA] [--slippage 0.5]
 *   dca.js list
 *   dca.js remove <id>
 *   dca.js run <id>     -- manually execute once
 *   dca.js history <id> -- execution history for this DCA job
 */
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const S = process.env.AAWP_SKILL || require('path').resolve(__dirname, '..');
const JOBS_FILE    = path.join(S, '.dca-jobs.json');
const HISTORY_FILE = path.join(S, '.dca-history.json');

// ── Storage ──────────────────────────────────────────────────────────────────
function loadJobs() {
  try { return JSON.parse(fs.readFileSync(JOBS_FILE, 'utf8')); }
  catch { return []; }
}
function saveJobs(jobs) { fs.writeFileSync(JOBS_FILE, JSON.stringify(jobs, null, 2)); }

function loadHistory() {
  try { return JSON.parse(fs.readFileSync(HISTORY_FILE, 'utf8')); }
  catch { return []; }
}
function saveHistory(h) { fs.writeFileSync(HISTORY_FILE, JSON.stringify(h, null, 2)); }

// ── Parse args ───────────────────────────────────────────────────────────────
function parseArgs(args) {
  const opts = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--chain'    && args[i+1]) { opts.chain    = args[++i]; continue; }
    if (args[i] === '--from'     && args[i+1]) { opts.from     = args[++i]; continue; }
    if (args[i] === '--to'       && args[i+1]) { opts.to       = args[++i]; continue; }
    if (args[i] === '--amount'   && args[i+1]) { opts.amount   = args[++i]; continue; }
    if (args[i] === '--cron'     && args[i+1]) { opts.cron     = args[++i]; continue; }
    if (args[i] === '--name'     && args[i+1]) { opts.name     = args[++i]; continue; }
    if (args[i] === '--slippage' && args[i+1]) { opts.slippage = args[++i]; continue; }
    if (!args[i].startsWith('--')) opts._pos = opts._pos || [], opts._pos.push(args[i]);
  }
  return opts;
}

// ── Register OpenClaw cron ───────────────────────────────────────────────────
function registerCron(job) {
  const cronPayload = JSON.stringify({
    name: `aawp-dca-${job.id}`,
    trigger: { kind: 'cron', expr: job.cron, tz: 'Asia/Hong_Kong' },
    action: { kind: 'agentTurn', message: `Run AAWP DCA: node ${path.join(S, 'scripts/dca.js')} run ${job.id}` },
  });
  const runCmd = `node ${path.join(S, 'scripts/dca.js')} run ${job.id}`;
  // Try OpenClaw cron first
  try {
    execSync(`command -v openclaw`, { stdio: 'pipe' });
    execSync(`openclaw cron add '${cronPayload.replace(/'/g, "'\\''")}'`, { stdio: 'pipe', timeout: 10000 });
    console.log(`  ✅ Scheduled via OpenClaw cron`);
    return true;
  } catch { /* OpenClaw not available */ }
  // Fallback: system crontab
  try {
    const cronLine = `${job.cron} ${runCmd} >> /tmp/aawp-dca.log 2>&1`;
    const existing = execSync('crontab -l 2>/dev/null || true', { encoding: 'utf8' });
    if (!existing.includes(job.id)) {
      execSync(`(crontab -l 2>/dev/null; echo '${cronLine}') | crontab -`, { stdio: 'pipe' });
      console.log(`  ✅ Scheduled via system crontab`);
      return true;
    }
    return true;
  } catch { /* crontab not available */ }
  // Manual fallback
  console.log(`  ⚠️  No scheduler available. Run manually or add to crontab:`);
  console.log(`  Cron: ${job.cron}`);
  console.log(`  Command: ${runCmd}`);
  return false;
}

function removeCron(jobId) {
  // Try OpenClaw
  try { execSync(`openclaw cron remove aawp-dca-${jobId}`, { stdio: 'pipe', timeout: 10000 }); return; } catch {}
  // Try system crontab
  try {
    const existing = execSync('crontab -l 2>/dev/null', { encoding: 'utf8' });
    const filtered = existing.split('\n').filter(l => !l.includes(jobId)).join('\n');
    execSync(`echo '${filtered}' | crontab -`, { stdio: 'pipe' });
  } catch { /* best effort */ }
}

// ── Commands ─────────────────────────────────────────────────────────────────

function addJob(opts) {
  if (!opts.chain || !opts.from || !opts.to || !opts.amount || !opts.cron) {
    console.log('Usage: dca.js add --chain <chain> --from <token> --to <token> --amount <amt> --cron "<expr>" [--name <name>] [--slippage <pct>]');
    process.exit(1);
  }

  const jobs = loadJobs();
  const job = {
    id:         crypto.randomBytes(4).toString('hex'),
    name:       opts.name || `${opts.from}→${opts.to}`,
    chain:      opts.chain.toLowerCase(),
    fromToken:  opts.from.toUpperCase(),
    toToken:    opts.to.toUpperCase(),
    amount:     opts.amount,
    slippage:   opts.slippage || '0.5',
    cron:       opts.cron,
    createdAt:  new Date().toISOString(),
    lastRun:    null,
    totalRuns:  0,
    totalSpent: '0',
    cronRegistered: false,
  };

  job.cronRegistered = registerCron(job);
  jobs.push(job);
  saveJobs(jobs);

  console.log(`\n✅ DCA job created: ${job.id}`);
  console.log(`   ${job.amount} ${job.fromToken} → ${job.toToken} on ${job.chain.toUpperCase()}`);
  console.log(`   Schedule: ${job.cron} (Asia/Hong_Kong)`);
}

function listJobs() {
  const jobs = loadJobs();
  if (jobs.length === 0) { console.log('No DCA jobs configured.'); return; }

  console.log('=== AAWP DCA Jobs ===\n');
  for (const j of jobs) {
    console.log(`  [${j.id}] ${j.name}`);
    console.log(`    ${j.amount} ${j.fromToken} → ${j.toToken} on ${j.chain.toUpperCase()}`);
    console.log(`    Cron: ${j.cron} | Runs: ${j.totalRuns} | Last: ${j.lastRun || 'never'}`);
    console.log(`    Total spent: ${j.totalSpent} ${j.fromToken} | Cron registered: ${j.cronRegistered ? '✅' : '❌'}`);
    console.log('');
  }
}

function removeJob(id) {
  if (!id) { console.log('Usage: dca.js remove <id>'); process.exit(1); }
  const jobs = loadJobs();
  const idx = jobs.findIndex(j => j.id === id);
  if (idx === -1) { console.log(`❌ Job not found: ${id}`); process.exit(1); }
  removeCron(id);
  const removed = jobs.splice(idx, 1)[0];
  saveJobs(jobs);
  console.log(`✅ Removed DCA job: ${removed.name} (${id})`);
}

async function runJob(id) {
  if (!id) { console.log('Usage: dca.js run <id>'); process.exit(1); }
  const jobs = loadJobs();
  const job = jobs.find(j => j.id === id);
  if (!job) { console.log(`❌ Job not found: ${id}`); process.exit(1); }

  console.log(`\n🔄 Executing DCA: ${job.amount} ${job.fromToken} → ${job.toToken} on ${job.chain.toUpperCase()}`);

  const swapModule = require(path.join(S, 'scripts/swap.js'));
  const history = loadHistory();
  const entry = {
    jobId: id,
    timestamp: new Date().toISOString(),
    amount: job.amount,
    fromToken: job.fromToken,
    toToken: job.toToken,
    chain: job.chain,
    status: 'pending',
    error: null,
  };

  try {
    await swapModule.swap(job.chain, job.fromToken, job.toToken, job.amount);
    entry.status = 'success';
    job.totalRuns++;
    job.totalSpent = String(parseFloat(job.totalSpent) + parseFloat(job.amount));
    job.lastRun = entry.timestamp;
    console.log(`\n✅ DCA execution successful`);
  } catch (e) {
    entry.status = 'failed';
    entry.error = e.message;
    job.totalRuns++;
    job.lastRun = entry.timestamp;
    console.error(`\n❌ DCA execution failed: ${e.message}`);
  }

  history.push(entry);
  saveHistory(history);
  saveJobs(jobs);
}

function showHistory(id) {
  if (!id) { console.log('Usage: dca.js history <id>'); process.exit(1); }
  const history = loadHistory().filter(h => h.jobId === id);
  if (history.length === 0) { console.log(`No history for job ${id}`); return; }

  console.log(`=== DCA History: ${id} ===\n`);
  for (const h of history.slice(-20)) {
    const icon = h.status === 'success' ? '✅' : '❌';
    console.log(`  ${icon} ${h.timestamp} | ${h.amount} ${h.fromToken} → ${h.toToken} | ${h.status}${h.error ? ' | ' + h.error : ''}`);
  }
  console.log(`\nTotal entries: ${history.length}`);
}

// ── Main ─────────────────────────────────────────────────────────────────────
async function main() {
  const args = process.argv.slice(2);
  const cmd = args[0];
  const opts = parseArgs(args.slice(1));

  switch (cmd) {
    case 'add':     addJob(opts); break;
    case 'list':    listJobs(); break;
    case 'remove':  removeJob(opts._pos?.[0] || args[1]); break;
    case 'run':     await runJob(opts._pos?.[0] || args[1]); break;
    case 'history': showHistory(opts._pos?.[0] || args[1]); break;
    default:
      console.log(`AAWP DCA — Dollar Cost Averaging

Usage:
  dca.js add --chain <chain> --from <token> --to <token> --amount <amt> --cron "<expr>" [--name <name>]
  dca.js list
  dca.js remove <id>
  dca.js run <id>
  dca.js history <id>

Examples:
  dca.js add --chain base --from ETH --to USDC --amount 0.01 --cron "0 9 * * *" --name "Daily ETH→USDC"
  dca.js run abc123
`);
  }
}

main().catch(e => { console.error('❌', e.message); process.exit(1); });

#!/usr/bin/env node
/**
 * deploy-clanker.js — Deploy a token on Clanker V4 via your AAWP wallet
 *
 * Supported chains (Clanker V4):
 *   base (8453) · eth (1) · arb (42161) · unichain (130) · bera (143) · bsc (56)
 *
 * Usage:
 *   node deploy-clanker.js              # interactive prompts
 *   node deploy-clanker.js --dry-run    # preview config only, no broadcast
 *
 * Or fill in CONFIG below and run directly.
 */

'use strict';
const { execFileSync } = require('child_process');
const readline         = require('readline');
const path             = require('path');

const SKILL = path.resolve(__dirname, '..');
const WM    = path.resolve(SKILL, 'scripts/wallet-manager.js');

const { createPublicClient, http, encodeFunctionData, formatEther } = require('viem');
const { base, mainnet, arbitrum, bsc }  = require('viem/chains');
const { Clanker }                                         = require('clanker-sdk/v4');
const { ClankerDeployments, POOL_POSITIONS, FEE_CONFIGS } = require('clanker-sdk');

const DRY_RUN = process.argv.includes('--dry-run');

// ─────────────────────────────────────────────────────────────────────────────
// CHAIN CONFIG
// ─────────────────────────────────────────────────────────────────────────────
const CHAINS = {
  base:     { id: 8453,  name: 'Base',      rpc: 'https://mainnet.base.org',           viemChain: base,    explorer: 'https://basescan.org' },
  eth:      { id: 1,     name: 'Ethereum',  rpc: 'https://eth.llamarpc.com',            viemChain: mainnet, explorer: 'https://etherscan.io' },
  arb:      { id: 42161, name: 'Arbitrum',  rpc: 'https://arb1.arbitrum.io/rpc',       viemChain: arbitrum,explorer: 'https://arbiscan.io' },
  unichain: { id: 130,   name: 'Unichain',  rpc: 'https://mainnet.unichain.org',       viemChain: base,    explorer: 'https://uniscan.xyz' },
  bera:     { id: 143,   name: 'Berachain', rpc: 'https://rpc.berachain.com',          viemChain: base,    explorer: 'https://berascan.com' },
  bsc:      { id: 56,    name: 'BSC',       rpc: 'https://bsc-dataseed1.binance.org',  viemChain: bsc,     explorer: 'https://bscscan.com' },
};

// ─────────────────────────────────────────────────────────────────────────────
// ★ EDIT THIS SECTION TO CONFIGURE YOUR TOKEN ★
// ─────────────────────────────────────────────────────────────────────────────
const CONFIG = {

  // ── Chain ──────────────────────────────────────────────────────────────────
  chain: 'base',            // base | eth | arb | unichain | bera | bsc

  // ── Token identity ─────────────────────────────────────────────────────────
  name:        'My Token',
  symbol:      'MTK',
  image:       'https://example.com/logo.png',  // Square image URL (1:1 ratio)
  description: 'A short description of what this token is about.',
  website:     '',                               // Optional: https://yoursite.com
  twitter:     '',                               // Optional: https://x.com/yourhandle

  // ── Pool / market cap ──────────────────────────────────────────────────────
  initialMarketCap: 10,       // ETH value at launch (min ~10 ETH ≈ $25K FDV)
  poolPositions:    'Standard',   // Standard | Project | TwentyETH
  feeConfig:        'StaticBasic',// StaticBasic (1%) | DynamicBasic | Dynamic3

  // ── Dev buy ────────────────────────────────────────────────────────────────
  devBuyEth: 0.003,           // ETH to spend buying at launch. 0 to skip.

  // ── Vault (optional) ───────────────────────────────────────────────────────
  vault: {
    enabled:     false,       // set true to enable
    percentage:  20,          // % of total supply to lock (1–90)
    lockupDays:  7,           // cliff before any unlock (min 7 days)
    vestingDays: 180,         // linear vesting after cliff (0 = instant after cliff)
    // recipient defaults to tokenAdmin (AAWP wallet)
  },

  // ── Admin & rewards ────────────────────────────────────────────────────────
  // null = use AAWP wallet automatically
  tokenAdmin:      null,
  rewardRecipient: null,
};
// ─────────────────────────────────────────────────────────────────────────────

// ── Helpers ──────────────────────────────────────────────────────────────────
const bold   = s => `\x1b[1m${s}\x1b[0m`;
const green  = s => `\x1b[32m${s}\x1b[0m`;
const cyan   = s => `\x1b[36m${s}\x1b[0m`;
const yellow = s => `\x1b[33m${s}\x1b[0m`;
const red    = s => `\x1b[31m${s}\x1b[0m`;

function ask(rl, q) {
  return new Promise(r => rl.question(q, r));
}

function getAawpWallet() {
  if (process.env.AAWP_WALLET) return process.env.AAWP_WALLET;
  try {
    const out = execFileSync(process.execPath, [WM, '--chain', CONFIG.chain, 'status'], {
      encoding: 'utf8', timeout: 15_000, env: { ...process.env },
    });
    const m = out.match(/Wallet[:\s]+0x([0-9a-fA-F]{40})/i) ||
              out.match(/(0x[0-9a-fA-F]{40})/);
    if (m) return m[0].startsWith('0x') ? m[0] : '0x' + m[1];
  } catch {}
  throw new Error(
    'Could not resolve AAWP wallet. Set AAWP_WALLET env or run:\n  node scripts/wallet-manager.js status'
  );
}

// ── Main ─────────────────────────────────────────────────────────────────────
async function main() {
  const chain = CHAINS[CONFIG.chain];
  if (!chain) {
    console.error(red(`Unknown chain "${CONFIG.chain}". Supported: ${Object.keys(CHAINS).join(', ')}`));
    process.exit(1);
  }

  const clankerDeps = ClankerDeployments[chain.id];
  if (!clankerDeps?.clanker_v4) {
    console.error(red(`Clanker V4 not deployed on "${CONFIG.chain}" (chainId: ${chain.id})`));
    process.exit(1);
  }
  const FACTORY = clankerDeps.clanker_v4.address;

  let walletAddr;
  try { walletAddr = getAawpWallet(); }
  catch (e) { console.error(red(e.message)); process.exit(1); }

  const tokenAdmin      = CONFIG.tokenAdmin      ?? walletAddr;
  const rewardRecipient = CONFIG.rewardRecipient ?? walletAddr;

  // ── Config summary ─────────────────────────────────────────────────────────
  console.log('\n' + bold('═══════════════════════════════════════════════'));
  console.log(bold('  Clanker V4 Token Deploy'));
  console.log(bold('═══════════════════════════════════════════════'));
  console.log(`  Chain        : ${cyan(chain.name)} (${chain.id})`);
  console.log(`  Factory      : ${FACTORY}`);
  console.log(`  Name / Ticker: ${bold(CONFIG.name)} / $${CONFIG.symbol}`);
  console.log(`  Image        : ${CONFIG.image}`);
  console.log(`  Initial MCAP : ${CONFIG.initialMarketCap} ETH`);
  console.log(`  Dev buy      : ${CONFIG.devBuyEth} ETH`);
  console.log(`  Fee config   : ${CONFIG.feeConfig}`);
  console.log(`  Pool         : ${CONFIG.poolPositions}`);
  console.log(`  Token admin  : ${tokenAdmin}`);
  console.log(`  LP rewards → : ${rewardRecipient}`);
  if (CONFIG.vault.enabled) {
    console.log(`  Vault        : ${yellow(`${CONFIG.vault.percentage}% | cliff ${CONFIG.vault.lockupDays}d + vest ${CONFIG.vault.vestingDays}d linear`)}`);
  } else {
    console.log(`  Vault        : none (fair launch)`);
  }
  if (CONFIG.website) console.log(`  Website      : ${CONFIG.website}`);
  if (CONFIG.twitter) console.log(`  Twitter      : ${CONFIG.twitter}`);
  console.log('');

  if (DRY_RUN) {
    console.log(yellow('DRY RUN — no transaction broadcast.'));
    return;
  }

  // Interactive confirmation
  if (process.stdin.isTTY) {
    const rl  = readline.createInterface({ input: process.stdin, output: process.stdout });
    const ans = await ask(rl, `Deploy ${bold('$' + CONFIG.symbol)} on ${chain.name}? (yes/no): `);
    rl.close();
    if (ans.trim().toLowerCase() !== 'yes') {
      console.log('Cancelled.');
      process.exit(0);
    }
    console.log('');
  }

  // ── Build token config ─────────────────────────────────────────────────────
  const socialUrls = [];
  if (CONFIG.twitter) socialUrls.push({ platform: 'x',       url: CONFIG.twitter });
  if (CONFIG.website) socialUrls.push({ platform: 'website', url: CONFIG.website });

  const tokenConfig = {
    chainId: chain.id,
    name:    CONFIG.name,
    symbol:  CONFIG.symbol,
    image:   CONFIG.image,
    metadata: {
      description: CONFIG.description,
      ...(socialUrls.length ? { socialMediaUrls: socialUrls } : {}),
    },
    context: {
      interface: 'AAWP',
      platform:  'AAWP',
      messageId: `${CONFIG.symbol.toLowerCase()}-${Date.now()}`,
      id:        CONFIG.symbol,
    },
    tokenAdmin,
    pool: {
      pairedToken:      'WETH',
      initialMarketCap: CONFIG.initialMarketCap,
      positions:        POOL_POSITIONS[CONFIG.poolPositions],
    },
    fees:    FEE_CONFIGS[CONFIG.feeConfig],
    rewards: {
      recipients: [{
        admin:     tokenAdmin,
        recipient: rewardRecipient,
        bps:       10000,
        token:     'Both',
      }],
    },
    ...(CONFIG.devBuyEth > 0 ? { devBuy: { ethAmount: CONFIG.devBuyEth } } : {}),
    ...(CONFIG.vault.enabled ? {
      vault: {
        percentage:      CONFIG.vault.percentage,
        lockupDuration:  CONFIG.vault.lockupDays  * 86400,
        vestingDuration: CONFIG.vault.vestingDays * 86400,
        recipient:       rewardRecipient,
      },
    } : {}),
  };

  // ── Get deploy calldata ────────────────────────────────────────────────────
  console.log('Building calldata...');
  const publicClient = createPublicClient({
    chain: { ...chain.viemChain, id: chain.id },
    transport: http(chain.rpc),
  });
  const clanker  = new Clanker({ publicClient });
  const tx       = await clanker.getDeployTransaction(tokenConfig);
  const calldata = encodeFunctionData({ abi: tx.abi, functionName: tx.functionName, args: tx.args });

  console.log(`  Calldata : ${calldata.length / 2 - 1} bytes`);
  console.log(`  Value    : ${formatEther(tx.value ?? 0n)} ETH\n`);

  // ── Send via AAWP wallet ───────────────────────────────────────────────────
  console.log(`Sending via AAWP wallet ${walletAddr}...`);
  const result = execFileSync(process.execPath, [
    WM,
    '--chain', CONFIG.chain,
    'call',
    '--value',     String(CONFIG.devBuyEth > 0 ? CONFIG.devBuyEth : 0),
    '--gas-limit', '8000000',
    FACTORY,
    calldata,
  ], {
    encoding: 'utf8',
    timeout:  120_000,
    env: { ...process.env, AAWP_WALLET: walletAddr },
  });

  console.log(result);

  // ── Extract token address from receipt ────────────────────────────────────
  const txMatch = result.match(/\/tx\/(0x[0-9a-fA-F]{64})/i) ||
                  result.match(/TX[:\s]+(0x[0-9a-fA-F]{64})/i);
  if (txMatch) {
    try {
      const receipt = await publicClient.getTransactionReceipt({ hash: txMatch[1] });
      const addr    = receipt.logs[0]?.address;
      console.log(green('═══════════════════════════════════'));
      console.log(green('  ✅ Token deployed!'));
      console.log(green('═══════════════════════════════════'));
      if (addr) {
        console.log(`\n  Token    : ${bold(addr)}`);
        console.log(`  Explorer : ${chain.explorer}/address/${addr}`);
        console.log(`  Clanker  : https://clanker.world/clanker/${addr}`);
      }
      console.log(`  TX       : ${chain.explorer}/tx/${txMatch[1]}\n`);
    } catch {}
  }
}

main().catch(e => {
  console.error(red('\n' + (e.shortMessage || e.message || e)));
  if (e.stderr) console.error(e.stderr.toString());
  process.exit(1);
});

#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
LOCK="/tmp/.aawp-daemon.lock"

# Bootstrap: download missing binaries if needed
bash "$SCRIPT_DIR/bootstrap.sh"
OUT="/tmp/aawp-ensure.out"

cd "$ROOT"

# Auto-provision on first run
if [ ! -f "$ROOT/.agent-config/seed.enc" ]; then
  echo "[AAWP] Not provisioned — running first-time setup..."
  bash "$ROOT/scripts/provision.sh"
  exit $?
fi

healthcheck() {
  AAWP_SKILL="$ROOT" AAWP_CONFIG="$ROOT/.agent-config" AAWP_CORE="$ROOT/core/aawp-core.node" \
  node - <<'NODE'
const fs = require('fs');
const net = require('net');
const path = require('path');
const S = process.env.AAWP_SKILL;
const C = process.env.AAWP_CONFIG;
const addon = require(process.env.AAWP_CORE);
const lockPath = '/tmp/.aawp-daemon.lock';

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

function query(sock, payload, timeoutMs = 3000) {
  return new Promise((resolve, reject) => {
    const ts = Math.floor(Date.now() / 1000);
    const hmac = addon._h0(ts);
    const req = JSON.stringify({ ...payload, ts, hmac });
    const c = net.createConnection(sock, () => c.end(req));
    let data = '';
    const timer = setTimeout(() => {
      c.destroy();
      reject(new Error('timeout'));
    }, timeoutMs);
    c.on('data', chunk => { data += chunk; });
    c.on('end', () => {
      clearTimeout(timer);
      try { resolve(JSON.parse(data)); }
      catch (_) { reject(new Error('invalid json')); }
    });
    c.on('error', err => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

(async () => {
  let lock;
  try {
    lock = JSON.parse(fs.readFileSync(lockPath, 'utf8'));
  } catch (_) {
    fail('no lock');
  }
  if (!lock.sock || !fs.existsSync(lock.sock)) fail('missing socket');

  addon._i0(C, S);
  const res = await query(lock.sock, { cmd: 'address' });
  if (!res || !res.address) fail('bad healthcheck response');
  console.log(res.address);
})().catch(err => fail(err && err.message ? err.message : String(err)));
NODE
}

if healthcheck > "$OUT" 2>&1; then
  echo "[AAWP] daemon healthy"
  cat "$OUT"
  exit 0
fi

echo "[AAWP] daemon unhealthy — restarting"
"$SCRIPT_DIR/restart-daemon.sh"

#!/usr/bin/env node
/**
 * AAWP Limit Order Manager — CoW Protocol
 *
 * Creates gasless limit orders via CoW Protocol (EIP-712 signed, no on-chain gas).
 * Supported chains: eth, base, arb, op, polygon
 *
 * Usage:
 *   limit-order.js --chain base create ETH USDC 0.1 2700     Sell 0.1 ETH if price >= 2700 USDC
 *   limit-order.js --chain base create USDC ETH 1000 0.00037 Buy ETH with 1000 USDC at 0.00037 ETH/USDC
 *   limit-order.js --chain base list                          List open orders
 *   limit-order.js --chain base cancel <orderUid>            Cancel an order
 *   limit-order.js --chain base history                       Filled/expired orders
 *
 * How it works:
 *   1. Get token addresses and decimals from config
 *   2. Call CoW API to get quote (for order hash)
 *   3. Sign the EIP-712 order via AAWP daemon
 *   4. POST signed order to CoW API — no gas paid by user
 */
'use strict';

const net = require('net');
const { ethers } = require('ethers');
const fs = require('fs');
const path = require('path');
const https = require('https');

const S = path.join(__dirname, '..');
const ENSURE_SCRIPT = path.join(__dirname, 'ensure-daemon.sh');
const CHAINS_FILE = path.join(S, 'config/chains.json');
const CHAINS = JSON.parse(fs.readFileSync(CHAINS_FILE, 'utf8'));

// ── CoW Protocol config (non-BSC chains) ─────────────────────────────────────
const COW_API = {
  eth:     'https://api.cow.fi/mainnet',
  base:    'https://api.cow.fi/base',
  arb:     'https://api.cow.fi/arbitrum_one',
  op:      'https://api.cow.fi/optimism',
  polygon: 'https://api.cow.fi/polygon',
};

// ── 1inch Limit Order Protocol (BSC) ─────────────────────────────────────────
// 1inch Limit Order Contract v4 on BSC
const INCH_LO_CONTRACT_BSC = '0x111111125421cA6dc452d289314280a0f8842A65';
const INCH_API_BSC = 'https://api.1inch.dev/orderbook/v4.0/56';

// 1inch Limit Order EIP-712 domain + types
const INCH_DOMAIN_BSC = {
  name: '1inch Aggregation Router',
  version: '6',
  chainId: 56,
  verifyingContract: INCH_LO_CONTRACT_BSC,
};

const INCH_ORDER_TYPES = {
  Order: [
    { name: 'salt',           type: 'uint256' },
    { name: 'maker',          type: 'address' },
    { name: 'receiver',       type: 'address' },
    { name: 'makerAsset',     type: 'address' },
    { name: 'takerAsset',     type: 'address' },
    { name: 'makingAmount',   type: 'uint256' },
    { name: 'takingAmount',   type: 'uint256' },
    { name: 'makerTraits',    type: 'uint256' },
  ],
};

// CoW Protocol settlement contract (same on all chains)
