// ── CoinGecko symbol → ID mapping ─────────────────────────────────────────────
const CG_IDS = {
  ETH: 'ethereum', WETH: 'ethereum',
  BTC: 'bitcoin',  WBTC: 'wrapped-bitcoin', BTCB: 'bitcoin',
  BNB: 'binancecoin', WBNB: 'wbnb',
  MATIC: 'matic-network', WMATIC: 'wmatic', POL: 'matic-network',
  USDC: 'usd-coin', USDT: 'tether', DAI: 'dai', BUSD: 'binance-usd', USDbC: 'usd-coin',
  ARB: 'arbitrum', OP: 'optimism', LINK: 'chainlink',
  UNI: 'uniswap', CAKE: 'pancakeswap-token', XVS: 'venus',
  AERO: 'aerodrome-finance', GMX: 'gmx', PEPE: 'pepe', cbBTC: 'coinbase-wrapped-btc',
};

// ── Parse args ────────────────────────────────────────────────────────────────
const argv = process.argv.slice(2);
let chainFilter = null;
let noPrices    = false;
let jsonOut     = false;
let hideZero    = false;
for (let i = 0; i < argv.length; i++) {
  if (argv[i] === '--chain' && argv[i + 1]) chainFilter = argv[++i];
  else if (argv[i] === '--no-prices')        noPrices    = true;
  else if (argv[i] === '--json')             jsonOut     = true;
  else if (argv[i] === '--hide-zero')        hideZero    = true;
}

// ── Daemon ────────────────────────────────────────────────────────────────────
function getSock() {
  try { require('child_process').execSync(`bash "${ENSURE_SCRIPT}"`, { stdio: 'ignore' }); } catch {}
  const lockFile = '/tmp/.aawp-daemon.lock';
  if (!fs.existsSync(lockFile)) throw new Error('Daemon not running. Run: bash scripts/ensure-daemon.sh');
  const lines = fs.readFileSync(lockFile, 'utf8').trim().split('\n');
  if (!lines[1]) throw new Error('Socket path not found in lock file');
  return lines[1];
}

function socketQuery(obj) {
  const sock = getSock();
  return new Promise((resolve, reject) => {
    const c = net.createConnection(sock, () => c.end(JSON.stringify(obj)));
    let d = '';
    c.on('data', x => d += x);
    c.on('end', () => { try { resolve(JSON.parse(d)); } catch { reject(new Error('Bad response: ' + d)); } });
    c.on('error', reject);
    setTimeout(() => { c.destroy(); reject(new Error('Daemon timeout')); }, 15000);
  });
}

async function getWalletAddress(chain) {
  // Try AAWP_WALLET env first
  if (process.env.AAWP_WALLET) return process.env.AAWP_WALLET;

  const [addrResp, hashResp] = await Promise.all([
    socketQuery({ cmd: 'address' }),
    socketQuery({ cmd: 'logichash' }),
  ]);
  if (addrResp.error) throw new Error(addrResp.error);

  // Load guardian
  const guardianFile = path.join(S, 'config/guardian.json');
  const guardian = JSON.parse(fs.readFileSync(guardianFile, 'utf8'));

  const provider = new ethers.JsonRpcProvider(chain.rpcOverride || chain.rpc);
  const factory  = new ethers.Contract(chain.factory, FACTORY_ABI, provider);
  return await factory.computeAddress(addrResp.address, hashResp.logicHash, guardian.address);
}

// ── CoinGecko price fetch ─────────────────────────────────────────────────────
function fetchPrices(symbols) {
  const ids = [...new Set(symbols.map(s => CG_IDS[s]).filter(Boolean))];
  if (!ids.length) return Promise.resolve({});

  return new Promise((resolve) => {
    const url = `https://api.coingecko.com/api/v3/simple/price?ids=${ids.join(',')}&vs_currencies=usd`;
    https.get(url, { headers: { 'User-Agent': 'AAWP-Portfolio/1.0' } }, res => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => {
        try {
          const raw = JSON.parse(data);
          // Map back: { SYMBOL: usdPrice }
          const out = {};
          for (const sym of symbols) {
            const id = CG_IDS[sym];
            if (id && raw[id]?.usd) out[sym] = raw[id].usd;
          }
          resolve(out);
        } catch { resolve({}); }
      });
    }).on('error', () => resolve({}));
  });
}

// ── Per-chain balance query ───────────────────────────────────────────────────
async function queryChain(chainKey, cfg, walletAddr) {
  const provider = new ethers.JsonRpcProvider(cfg.rpcOverride || cfg.rpc);
  const tokens   = EXTRA_TOKENS[chainKey] || {};
  const result   = { chain: chainKey, name: cfg.name, wallet: walletAddr, native: null, tokens: [] };

  // Native balance
  try {
    const nativeBal = await provider.getBalance(walletAddr);
    result.native = {
      symbol:   cfg.nativeCurrency,
      balance:  ethers.formatEther(nativeBal),
      raw:      nativeBal.toString(),
      decimals: 18,
    };
  } catch (e) {
    result.native = { symbol: cfg.nativeCurrency, balance: '0', raw: '0', decimals: 18, error: e.message };
  }

  // ERC-20 via Multicall3 (one RPC call for all tokens)
  const entries = Object.entries(tokens);
  if (entries.length > 0) {
    const calls = entries.flatMap(([, addr]) => [
      { target: addr, allowFailure: true, callData: ERC20_IFACE.encodeFunctionData('decimals') },
      { target: addr, allowFailure: true, callData: ERC20_IFACE.encodeFunctionData('balanceOf', [walletAddr]) },
    ]);

    try {
      const mc3     = new ethers.Contract(MC3_ADDR, MC3_ABI, provider);
      const results = await mc3.aggregate3(calls);

      for (let i = 0; i < entries.length; i++) {
        const [sym, addr] = entries[i];
        const decRes = results[i * 2];
        const balRes = results[i * 2 + 1];
        try {
          if (!decRes.success || !balRes.success) throw new Error('call failed');
          const dec = Number(ERC20_IFACE.decodeFunctionResult('decimals', decRes.returnData)[0]);
          const bal = ERC20_IFACE.decodeFunctionResult('balanceOf', balRes.returnData)[0];
          result.tokens.push({
            symbol:   sym,
            address:  addr,
            balance:  ethers.formatUnits(bal, dec),
            raw:      bal.toString(),
            decimals: dec,
          });
        } catch {
          result.tokens.push({ symbol: sym, address: addr, balance: '0', raw: '0', decimals: 18 });
        }
      }
    } catch {
      // Multicall not available, fall back to individual calls
      for (const [sym, addr] of entries) {
        try {
          const token = new ethers.Contract(addr, ERC20_IFACE, provider);
          const [dec, bal] = await Promise.all([token.decimals(), token.balanceOf(walletAddr)]);
          result.tokens.push({ symbol: sym, address: addr, balance: ethers.formatUnits(bal, Number(dec)), raw: bal.toString(), decimals: Number(dec) });
        } catch {
          result.tokens.push({ symbol: sym, address: addr, balance: '0', raw: '0', decimals: 18 });
        }
      }
    }
  }

  return result;
}

// ── Display ───────────────────────────────────────────────────────────────────
function formatBalance(bal, decimals = 4) {
  const n = parseFloat(bal);
  if (n === 0) return '0';
  if (n < 0.0001) return n.toExponential(2);
  return n.toFixed(decimals);
}

function formatUSD(val) {
  if (val === null || val === undefined) return '';
  if (val >= 1e6)  return `$${(val / 1e6).toFixed(2)}M`;
  if (val >= 1000) return `$${(val / 1000).toFixed(2)}K`;
  return `$${val.toFixed(2)}`;
}

// ── Main ──────────────────────────────────────────────────────────────────────
async function main() {
  const targetChains = chainFilter
    ? { [chainFilter]: CHAINS[chainFilter] }
    : CHAINS;

  if (!Object.keys(targetChains).length || (chainFilter && !CHAINS[chainFilter])) {
    console.error(`❌ Unknown chain: ${chainFilter}. Valid: ${Object.keys(CHAINS).join(', ')}`);
    process.exit(1);
  }

  if (!jsonOut) {
    console.log('\n🌐 AAWP Cross-Chain Portfolio');
    console.log('   Querying all chains in parallel...\n');
  }

  // Get wallet address (use first chain to compute — same address all chains)
  const firstChain = Object.entries(targetChains)[0];
  let walletAddr;
  try {
    walletAddr = await getWalletAddress({ ...firstChain[1] });
  } catch (e) {
    console.error(`❌ Cannot get wallet address: ${e.message}`);
    process.exit(1);
  }

  if (!jsonOut) {
    console.log(`   Wallet: ${walletAddr}\n`);
    console.log('   Fetching balances...');
  }

  // Query all chains in parallel
  const chainResults = await Promise.all(
    Object.entries(targetChains).map(([key, cfg]) =>
      queryChain(key, cfg, walletAddr).catch(e => ({
        chain: key, name: cfg.name, wallet: walletAddr,
        native: null, tokens: [], error: e.message,
      }))
    )
  );

  // Collect all unique symbols for price fetch
  let prices = {};
  if (!noPrices) {
    const allSymbols = new Set();
    for (const r of chainResults) {
      if (r.native) allSymbols.add(r.native.symbol);
      for (const t of r.tokens) allSymbols.add(t.symbol);
    }
    try {
      prices = await fetchPrices([...allSymbols]);
    } catch { /* prices stay empty */ }
  }

  // ── JSON output ──────────────────────────────────────────────────────────────
  if (jsonOut) {
    const out = { wallet: walletAddr, chains: chainResults, prices, timestamp: new Date().toISOString() };
    console.log(JSON.stringify(out, null, 2));
    return;
  }

  // ── Human-readable output ────────────────────────────────────────────────────
  let grandTotal = 0;
  const allRows  = []; // for summary table

  for (const r of chainResults) {
    if (r.error) {
      console.log(`\n❌ ${r.name.toUpperCase()} — Error: ${r.error}`);
      continue;
    }

    const chainTotal = { usd: 0 };
    const rows = [];

    // Native token
    if (r.native) {
      const bal = parseFloat(r.native.balance);
      const usdPrice = prices[r.native.symbol] || null;
      const usd = usdPrice ? bal * usdPrice : null;
      if (usd) chainTotal.usd += usd;
      if (!hideZero || bal > 0) {
        rows.push({ sym: r.native.symbol, bal, usd });
        allRows.push({ chain: r.chain, sym: r.native.symbol, bal, usd });
      }
    }

    // ERC-20 tokens
    for (const t of r.tokens) {
      const bal = parseFloat(t.balance);
      if (hideZero && bal < 0.000001) continue;
      const usdPrice = prices[t.symbol] || null;
      const usd = usdPrice ? bal * usdPrice : null;
      if (usd) chainTotal.usd += usd;
      rows.push({ sym: t.symbol, bal, usd });
      allRows.push({ chain: r.chain, sym: t.symbol, bal, usd });
    }

    grandTotal += chainTotal.usd;

    // Print chain section
    const chainUsdStr = chainTotal.usd > 0 ? `  ${formatUSD(chainTotal.usd)}` : '';
    console.log(`\n  ┌─ ${r.name.toUpperCase()}${chainUsdStr}`);
    for (const row of rows) {
      if (row.bal < 0.000001 && hideZero) continue;
      const balStr = formatBalance(row.bal).padStart(18);
      const usdStr = row.usd ? `  ${formatUSD(row.usd)}` : '';
      console.log(`  │  ${row.sym.padEnd(8)} ${balStr}${usdStr}`);
    }
    if (rows.length === 0) console.log('  │  (no balances)');
    console.log('  └' + '─'.repeat(40));
  }

  // ── Summary ───────────────────────────────────────────────────────────────────
  if (grandTotal > 0) {
    console.log(`\n${'─'.repeat(44)}`);
    console.log(`  TOTAL PORTFOLIO VALUE: ${formatUSD(grandTotal)}`);
    console.log(`${'─'.repeat(44)}`);
  }

  // ── Top holdings ──────────────────────────────────────────────────────────────
  const withUsd = allRows.filter(r => r.usd && r.usd > 0.01);
  if (withUsd.length > 1) {
    withUsd.sort((a, b) => b.usd - a.usd);
    console.log('\n  Top Holdings:');
    for (const r of withUsd.slice(0, 8)) {
      const pct = grandTotal > 0 ? ((r.usd / grandTotal) * 100).toFixed(1) + '%' : '';
      console.log(`    ${r.sym.padEnd(8)} on ${r.chain.padEnd(8)} ${formatBalance(r.bal).padStart(14)}  ${formatUSD(r.usd).padStart(10)}  ${pct}`);
    }
  }

  // ── Per-token aggregation (same token across chains) ──────────────────────────
  const bySymbol = {};
  for (const r of allRows) {
    if (!bySymbol[r.sym]) bySymbol[r.sym] = { bal: 0, usd: 0, chains: [] };
    bySymbol[r.sym].bal += r.bal;
    if (r.usd) bySymbol[r.sym].usd += r.usd;
    if (r.bal > 0.000001) bySymbol[r.sym].chains.push(r.chain);
  }

  const multiChain = Object.entries(bySymbol).filter(([, v]) => v.chains.length > 1 && v.bal > 0.000001);
  if (multiChain.length > 0) {
    console.log('\n  Multi-chain Holdings:');
    for (const [sym, v] of multiChain) {
      const usdStr = v.usd > 0 ? `  ${formatUSD(v.usd)}` : '';
      console.log(`    ${sym.padEnd(8)} ${formatBalance(v.bal).padStart(14)}${usdStr}  [${v.chains.join(', ')}]`);
    }
  }

  if (!noPrices && Object.keys(prices).length === 0) {
    console.log('\n  ⚠️  Price data unavailable (CoinGecko rate limited). Use --no-prices to skip.');
  }

  console.log();
}

main().catch(err => {
  console.error('❌ Error:', err.message);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * AAWP Price Alert — monitor token prices and notify/auto-swap
 *
 * Usage:
 *   price-alert.js add --chain base --from ETH --to USDC --above 2600 [--notify] [--auto-swap 0.01]
 *   price-alert.js add --chain base --from ETH --to USDC --below 2200 [--notify] [--auto-swap 0.01]
 *   price-alert.js list
 *   price-alert.js remove <id>
 *   price-alert.js check   -- manually check all alerts (called by cron)
 */
'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const https = require('https');
const { execSync } = require('child_process');

const S = process.env.AAWP_SKILL || require('path').resolve(__dirname, '..');
const ALERTS_FILE = path.join(S, '.price-alerts.json');
const CHAINS = JSON.parse(fs.readFileSync(path.join(S, 'config/chains.json'), 'utf8'));

const NATIVE = '0x0000000000000000000000000000000000000000';
const RELAY_API = 'https://api.relay.link';

// ── Helpers ──────────────────────────────────────────────────────────────────
function loadAlerts() {
  try { return JSON.parse(fs.readFileSync(ALERTS_FILE, 'utf8')); }
  catch { return []; }
}
function saveAlerts(a) { fs.writeFileSync(ALERTS_FILE, JSON.stringify(a, null, 2)); }

function resolveToken(chainKey, sym) {
  if (sym === 'ETH' || sym === 'BNB' || sym === 'MATIC' || sym.toLowerCase() === 'native') return NATIVE;
  if (sym.startsWith('0x') && sym.length === 42) return sym;
  const cfg = CHAINS[chainKey];
  const upper = sym.toUpperCase();
  if (cfg?.tokens?.[upper]) return cfg.tokens[upper];
  throw new Error(`Unknown token "${sym}" on ${chainKey}`);
}

function relayFetch(method, urlPath, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const url = new URL(RELAY_API + urlPath);
    const opts = {
      hostname: url.hostname, path: url.pathname + url.search, method,
      headers: { 'Content-Type': 'application/json', 'User-Agent': 'AAWP/1.0', ...(data ? { 'Content-Length': Buffer.byteLength(data) } : {}) },
      timeout: 15000,
    };
    const req = https.request(opts, (res) => {
      let raw = '';
      res.on('data', d => raw += d);
      res.on('end', () => { try { resolve(JSON.parse(raw)); } catch (e) { reject(new Error(`Parse error: ${raw.slice(0, 200)}`)); } });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
    if (data) req.write(data);
    req.end();
  });
}

/** Get price of 1 unit of fromToken denominated in toToken via Relay quote */
async function getPrice(chainKey, fromToken, toToken) {
  const { ethers } = require('ethers');
  const chain = CHAINS[chainKey];
  if (!chain) throw new Error(`Unknown chain: ${chainKey}`);

  const fromAddr = resolveToken(chainKey, fromToken);
  const toAddr = resolveToken(chainKey, toToken);

  // Use 1 unit of fromToken (18 decimals for native, query for ERC20)
  let decimals = 18;
  if (fromAddr !== NATIVE) {
    try {
      const p = new ethers.JsonRpcProvider(chain.rpcOverride || chain.rpc);
      const tok = new ethers.Contract(fromAddr, ['function decimals() view returns (uint8)'], p);
      decimals = Number(await tok.decimals());
    } catch {}
  }
  const amount = ethers.parseUnits('1', decimals).toString();

  // We need a user address for the quote — use zero address for quote-only
  const quote = await relayFetch('POST', '/quote/v2', {
    user: '0x0000000000000000000000000000000000000001',
    originChainId: chain.chainId,
    destinationChainId: chain.chainId,
    originCurrency: fromAddr,
    destinationCurrency: toAddr,
    amount,
    tradeType: 'EXACT_INPUT',
  });

  if (quote.message && !quote.details) {
    throw new Error(`Relay quote: ${quote.message}`);
  }

  const cout = quote.details?.currencyOut;
  if (!cout) throw new Error('No output in quote');
  const outDecimals = cout.currency?.decimals || 6;
  const outAmount = cout.amount?.amount || cout.amount || '0';
  return parseFloat(ethers.formatUnits(BigInt(outAmount), outDecimals));
}

// ── Parse args ───────────────────────────────────────────────────────────────
function parseArgs(args) {
  const opts = { notify: false, autoSwap: null };
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--chain'      && args[i+1]) { opts.chain     = args[++i]; continue; }
    if (args[i] === '--from'       && args[i+1]) { opts.from      = args[++i]; continue; }
    if (args[i] === '--to'         && args[i+1]) { opts.to        = args[++i]; continue; }
    if (args[i] === '--above'      && args[i+1]) { opts.above     = parseFloat(args[++i]); continue; }
    if (args[i] === '--below'      && args[i+1]) { opts.below     = parseFloat(args[++i]); continue; }
    if (args[i] === '--notify')                   { opts.notify    = true; continue; }
    if (args[i] === '--auto-swap'  && args[i+1]) { opts.autoSwap  = args[++i]; continue; }
    if (!args[i].startsWith('--')) opts._pos = opts._pos || [], opts._pos.push(args[i]);
  }
  return opts;
}

// ── Register cron (every 5 min check) ────────────────────────────────────────
let _cronRegistered = false;
function ensureCronRegistered() {
  if (_cronRegistered) return;
  const checkCmd = `node ${path.join(S, 'scripts/price-alert.js')} check`;
  // Try OpenClaw cron
  try {
    execSync(`command -v openclaw`, { stdio: 'pipe' });
    const payload = JSON.stringify({
      name: 'aawp-price-alert-check',
      trigger: { kind: 'cron', expr: '*/5 * * * *', tz: 'Asia/Hong_Kong' },
      action: { kind: 'agentTurn', message: `Run Price Alert check: ${checkCmd}` },
    });
    execSync(`openclaw cron add '${payload.replace(/'/g, "'\\''")}'`, { stdio: 'pipe', timeout: 10000 });
    _cronRegistered = true;
    return;
  } catch {}
  // Fallback: system crontab
  try {
    const cronLine = `*/5 * * * * ${checkCmd} >> /tmp/aawp-price-alert.log 2>&1`;
    const existing = execSync('crontab -l 2>/dev/null || true', { encoding: 'utf8' });
    if (!existing.includes('aawp-price-alert')) {
      execSync(`(crontab -l 2>/dev/null; echo '${cronLine}') | crontab -`, { stdio: 'pipe' });
    }
    _cronRegistered = true;
    return;
  } catch {}
  console.log(`  ⚠️  No scheduler available. Run manually: ${checkCmd}`);
}

// ── Commands ─────────────────────────────────────────────────────────────────

function addAlert(opts) {
  if (!opts.chain || !opts.from || !opts.to || (opts.above == null && opts.below == null)) {
    console.log('Usage: price-alert.js add --chain <chain> --from <token> --to <token> --above <price> | --below <price> [--notify] [--auto-swap <amount>]');
    process.exit(1);
  }

  const alerts = loadAlerts();
  const alert = {
    id:        crypto.randomBytes(4).toString('hex'),
    chain:     opts.chain.toLowerCase(),
    fromToken: opts.from.toUpperCase(),
    toToken:   opts.to.toUpperCase(),
    condition: opts.above != null ? 'above' : 'below',
    threshold: opts.above != null ? opts.above : opts.below,
    notify:    opts.notify,
    autoSwap:  opts.autoSwap,
    triggered: false,
    createdAt: new Date().toISOString(),
    triggeredAt: null,
  };

  alerts.push(alert);
  saveAlerts(alerts);
  ensureCronRegistered();

  console.log(`\n✅ Price alert created: ${alert.id}`);
  console.log(`   ${alert.fromToken}/${alert.toToken} ${alert.condition} ${alert.threshold} on ${alert.chain.toUpperCase()}`);
  if (alert.notify) console.log('   📱 Telegram notification enabled');
  if (alert.autoSwap) console.log(`   🔄 Auto-swap: ${alert.autoSwap} ${alert.fromToken}`);
}

function listAlerts() {
  const alerts = loadAlerts();
  if (alerts.length === 0) { console.log('No price alerts configured.'); return; }

  console.log('=== AAWP Price Alerts ===\n');
  for (const a of alerts) {
    const status = a.triggered ? '🔔 TRIGGERED' : '👀 watching';
    console.log(`  [${a.id}] ${a.fromToken}/${a.toToken} ${a.condition} ${a.threshold} (${a.chain.toUpperCase()}) — ${status}`);
    if (a.notify) process.stdout.write('    📱 notify');
    if (a.autoSwap) process.stdout.write(`    🔄 auto-swap ${a.autoSwap}`);
    if (a.triggeredAt) process.stdout.write(`    triggered: ${a.triggeredAt}`);
    console.log('');
  }
}

function removeAlert(id) {
  if (!id) { console.log('Usage: price-alert.js remove <id>'); process.exit(1); }
  const alerts = loadAlerts();
  const idx = alerts.findIndex(a => a.id === id);
  if (idx === -1) { console.log(`❌ Alert not found: ${id}`); process.exit(1); }
  alerts.splice(idx, 1);
  saveAlerts(alerts);
  console.log(`✅ Removed alert: ${id}`);
}

async function checkAlerts() {
  const alerts = loadAlerts();
  const active = alerts.filter(a => !a.triggered);
  if (active.length === 0) { console.log('No active alerts.'); return; }

  console.log(`Checking ${active.length} active alert(s)...\n`);
  let changed = false;

  for (const alert of active) {
    try {
      const price = await getPrice(alert.chain, alert.fromToken, alert.toToken);
      const met = (alert.condition === 'above' && price >= alert.threshold) ||
                  (alert.condition === 'below' && price <= alert.threshold);

      console.log(`  ${alert.fromToken}/${alert.toToken} = ${price.toFixed(4)} | threshold ${alert.condition} ${alert.threshold} → ${met ? '🔔 TRIGGERED' : 'not met'}`);

      if (met) {
        alert.triggered = true;
        alert.triggeredAt = new Date().toISOString();
        changed = true;

        const now = new Date().toLocaleString('en-US', { timeZone: 'Asia/Hong_Kong', hour12: false });

        // Notify via Telegram (best effort — output message for agent to pick up)
        if (alert.notify) {
          const msg = `⚡ Price Alert Triggered\n${alert.fromToken}/${alert.toToken} = ${price.toFixed(4)} (${alert.condition} ${alert.threshold})\nChain: ${alert.chain.toUpperCase()} | Time: ${now}`;
          console.log(`\n📱 NOTIFY:\n${msg}\n`);
          // Try openclaw message
          try {
            execSync(`echo '${msg.replace(/'/g, "'\\''")}' | openclaw message send --channel telegram`, { stdio: 'pipe', timeout: 10000 });
          } catch { /* agent will see console output */ }
        }

        // Auto-swap
        if (alert.autoSwap) {
          console.log(`\n🔄 Auto-swap: ${alert.autoSwap} ${alert.fromToken} → ${alert.toToken}`);
          try {
            const swapModule = require(path.join(S, 'scripts/swap.js'));
            await swapModule.swap(alert.chain, alert.fromToken, alert.toToken, alert.autoSwap);
            console.log('✅ Auto-swap complete');
          } catch (e) {
            console.error(`❌ Auto-swap failed: ${e.message}`);
          }
        }
      }
    } catch (e) {
      console.log(`  ❌ ${alert.fromToken}/${alert.toToken} on ${alert.chain}: ${e.message}`);
    }
  }

  if (changed) saveAlerts(alerts);
}

// ── Main ─────────────────────────────────────────────────────────────────────
async function main() {
  const args = process.argv.slice(2);
  const cmd = args[0];
  const opts = parseArgs(args.slice(1));

  switch (cmd) {
    case 'add':    addAlert(opts); break;
    case 'list':   listAlerts(); break;
    case 'remove': removeAlert(opts._pos?.[0] || args[1]); break;
    case 'check':  await checkAlerts(); break;
    default:
      console.log(`AAWP Price Alert — Monitor & Auto-Swap

Usage:
  price-alert.js add --chain <chain> --from <token> --to <token> --above <price> [--notify] [--auto-swap <amt>]
  price-alert.js add --chain <chain> --from <token> --to <token> --below <price> [--notify] [--auto-swap <amt>]
  price-alert.js list
  price-alert.js remove <id>
  price-alert.js check
`);
  }
}

main().catch(e => { console.error('❌', e.message); process.exit(1); });

'use strict';
// Standalone restore — no native addon, safe to run when shards are missing
const path = require('path');
const fs   = require('fs');
const { execSync } = require('child_process');

const C = process.env.AAWP_CONFIG || path.join(__dirname, '..', '.agent-config');
const S = process.env.AAWP_SKILL  || path.resolve(__dirname, '..');

const backupPath = process.argv[3];
if (!backupPath) { console.log('Usage: wallet-manager restore <backup.tar.gz>'); process.exit(1); }
if (!fs.existsSync(backupPath)) { console.log('❌ Not found:', backupPath); process.exit(1); }

const tmpDir = `/tmp/aawp-restore-${Date.now()}`;
fs.mkdirSync(tmpDir, { recursive: true });
console.log('Extracting...');
execSync(`tar xzf "${backupPath}" -C "${tmpDir}"`, { stdio: 'inherit' });

// Detect backup format: v2 (portable) has manifest.json, v1 (legacy) has absolute paths
const manifestPath = path.join(tmpDir, 'manifest.json');
const isV2 = fs.existsSync(manifestPath);

const copyIfExists = (src, dst) => {
  if (fs.existsSync(src)) {
    fs.mkdirSync(path.dirname(dst), { recursive: true });
    fs.copyFileSync(src, dst);
    console.log('  ✅', path.basename(dst));
    return true;
  }
  return false;
};

if (isV2) {
  // ── V2 portable format ──
  const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
  console.log(`Backup format: v${manifest.version} (${manifest.createdAt})`);

  copyIfExists(path.join(tmpDir, 'agent-config/seed.enc'),   path.join(C, 'seed.enc'));
  copyIfExists(path.join(tmpDir, 'core/aawp-core.node'),     path.join(S, 'core/aawp-core.node'));
  copyIfExists(path.join(tmpDir, 'system/fonts.idx'),         '/var/lib/aawp/.cache/fonts.idx');
  copyIfExists(path.join(tmpDir, 'system/machine-id'),        '/etc/machine-id');
  copyIfExists(path.join(tmpDir, 'system/host.salt'),         '/var/lib/aawp/host.salt');
  copyIfExists(path.join(tmpDir, 'config/guardian.json'),     path.join(S, 'config/guardian.json'));

  // Restore any additional agent-config files
  const acDir = path.join(tmpDir, 'agent-config');
  if (fs.existsSync(acDir)) {
    const walk = (dir, rel) => {
      for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, e.name);
        const r = path.join(rel, e.name);
        if (e.isDirectory()) walk(full, r);
        else copyIfExists(full, path.join(C, r));
      }
    };
    walk(acDir, '');
  }
} else {
  // ── V1 legacy format (absolute paths in tar) ──
  console.log('Backup format: v1 (legacy absolute paths)');

  const stripRoot = (abs) => path.join(tmpDir, abs);
  copyIfExists(stripRoot(C + '/seed.enc'),                        path.join(C, 'seed.enc'));
  copyIfExists(stripRoot(S + '/core/aawp-core.node'),             path.join(S, 'core/aawp-core.node'));
  copyIfExists(stripRoot('/var/lib/aawp/.cache/fonts.idx'),       '/var/lib/aawp/.cache/fonts.idx');
  copyIfExists(stripRoot('/etc/machine-id'),                      '/etc/machine-id');
  copyIfExists(stripRoot('/var/lib/aawp/host.salt'),              '/var/lib/aawp/host.salt');
  copyIfExists(stripRoot(S + '/config/guardian.json'),            path.join(S, 'config/guardian.json'));

  // Try legacy .agent-config path from backup manifest
  const backupCfg = stripRoot(C);
  if (fs.existsSync(backupCfg)) {
    execSync(`cp -r "${backupCfg}/." "${C}/"`, { stdio: 'inherit' });
    console.log('  ✅ .agent-config dir restored');
  }
}

// Regenerate binary hash
const corePath = path.join(S, 'core/aawp-core.node');
if (fs.existsSync(corePath)) {
  const hash = execSync(`sha256sum "${corePath}" | cut -d' ' -f1`).toString().trim();
  fs.writeFileSync(corePath + '.hash', hash);
  console.log(`  ✅ Hash regenerated: ${hash}`);
}

execSync(`rm -rf "${tmpDir}"`);
console.log('\n✅ Restore complete.');
console.log('\nNext steps:');
console.log('  1. Restart daemon:  bash scripts/restart-daemon.sh');
console.log('  2. Verify status:   node scripts/wallet-manager.js status\n');

#!/usr/bin/env node
'use strict';

const net = require('net');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const addon = require(process.env.AAWP_CORE || require('path').join(__dirname, '..', 'core', 'aawp-core.node'));

const C = process.env.AAWP_CONFIG || require('path').join(__dirname, '..', '.agent-config');
const LOCK = '/tmp/.aawp-daemon.lock';

function fail(msg) {
  process.stdout.write(JSON.stringify({ error: String(msg || 'worker failed') }));
  process.exit(1);
}

function readToken() {
  try {
    const persisted = fs.readFileSync('/tmp/.aawp-ai-token', 'utf8').trim();
    if (persisted && persisted.length === 64) return persisted;
  } catch (_) {}
  const envToken = process.env.AAWP_AI_TOKEN || '';
  if (envToken && envToken.length === 64) return envToken;
  return null;
}

function rotateLocalToken(current) {
  const next = crypto.createHmac('sha256', Buffer.from(current, 'hex')).update('rotate').digest('hex');
  try { fs.writeFileSync('/tmp/.aawp-ai-token', next, { mode: 0o600 }); } catch (_) {}
  return next;
}

function socketQuery(sock, obj, aiToken) {
  return new Promise((resolve, reject) => {
    const ts = Math.floor(Date.now() / 1000);
    const hmac = addon._h0(ts);
    const payload = { ...obj, ts, hmac, ai_token: aiToken };
    const c = net.createConnection(sock, () => c.end(JSON.stringify(payload)));
    let d = '';
    c.on('data', x => d += x);
    c.on('end', () => {
      try { resolve(JSON.parse(d)); } catch (e) { reject(new Error('bad response')); }
    });
    c.on('error', reject);
    setTimeout(() => { c.destroy(); reject(new Error('socket timeout')); }, 30000);
  });
}

(async () => {
  try {
    const arg = process.argv[2];
    if (!arg) fail('missing payload');
    const payload = JSON.parse(arg);

    let lockData;
    try { lockData = JSON.parse(fs.readFileSync(LOCK, 'utf8')); }
    catch (_) { fail('daemon not running'); }
    if (!lockData || !lockData.sock || !fs.existsSync(lockData.sock)) fail('daemon socket missing');

    const aiToken = readToken();
    if (!aiToken) fail('missing AAWP_AI_TOKEN');

    addon._i0(C, process.env.AAWP_SKILL || require('path').resolve(__dirname, '..'));

    // Inject guardian private key as gas_key for sign requests (replaces internal relay key)
    if (payload.cmd === 'sign' && !payload.gas_key) {
      try {
        const gPath = path.join(process.env.AAWP_SKILL || require('path').resolve(__dirname, '..'), 'config/guardian.json');
        const g = JSON.parse(fs.readFileSync(gPath, 'utf8'));
        if (g.privateKey) payload.gas_key = g.privateKey.replace(/^0x/, '');
      } catch (_) {}
    }

    const result = await socketQuery(lockData.sock, payload, aiToken);
    rotateLocalToken(aiToken);
    process.stdout.write(JSON.stringify(result));
    process.exit(0);
  } catch (err) {
    fail(err && err.message ? err.message : String(err));
  }
})();

'use strict';
/**
 * start-daemon.js — AAWP persistent daemon launcher
 * Must be called by OpenClaw ONLY. Generates AI gate token, arms daemon,
 * writes socket path to lock file. wallet-manager.js connects to this daemon.
 *
 * Usage: node start-daemon.js
 * Exits 0 on success, prints socket path to stdout.
 */
const crypto = require('crypto');
const fs = require('fs');
const net = require('net');
const addon = require('../core/aawp-core.node');
const C = process.env.AAWP_CONFIG || require('path').join(__dirname, '..', '.agent-config');
const S = process.env.AAWP_SKILL || require('path').resolve(__dirname, '..');
const LOCK = '/tmp/.aawp-daemon.lock';

// Generate random 32-byte AI gate token
const token = crypto.randomBytes(32).toString('hex');
process.env.AAWP_AI_TOKEN = token;

// Clean up stale lock/socket/token files from crashed daemon
try {
  const stale = JSON.parse(fs.readFileSync(LOCK, 'utf8'));
  if (stale.sock) try { fs.unlinkSync(stale.sock); } catch (_) {}
  fs.unlinkSync(LOCK);
} catch (_) {}
try { fs.unlinkSync('/tmp/.aawp-ai-token'); } catch (_) {}

function socketQuery(sock, payload, timeoutMs = 5000) {
  return new Promise((resolve, reject) => {
    const ts = Math.floor(Date.now() / 1000);
    const hmac = addon._h0(ts);
    const req = JSON.stringify({ ...payload, ts, hmac });
    const c = net.createConnection(sock, () => c.end(req));
    let data = '';
    const timer = setTimeout(() => {
      c.destroy();
      reject(new Error('healthcheck timeout'));
    }, timeoutMs);
    c.on('data', chunk => { data += chunk; });
    c.on('end', () => {
      clearTimeout(timer);
      try { resolve(JSON.parse(data)); }
      catch (_) { reject(new Error('invalid healthcheck response')); }
    });
    c.on('error', err => {
      clearTimeout(timer);
      reject(err);
    });
  });
}

async function waitForHealthy(sock, timeoutMs = 10000) {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (fs.existsSync(sock)) {
      try {
        const res = await socketQuery(sock, { cmd: 'address' }, 2000);
        if (res && res.address) return res;
      } catch (_) {}
    }
    await new Promise(r => setTimeout(r, 250));
  }
  throw new Error(`daemon healthcheck failed for socket ${sock}`);
}

async function main() {
  // Start daemon (reads env var, arms gate, clears env var internally)
  addon._l0(C, S, '/tmp/aawp.log');
  const sock = addon._x0();

  let health;
  try {
    health = await waitForHealthy(sock, 12000);
  } catch (err) {
    try { fs.unlinkSync(LOCK); } catch (_) {}
    console.error('[AAWP] startup failed:', err.message || err);
    process.exit(1);
  }

  // Write lock file only after successful healthcheck.
  fs.writeFileSync(LOCK, JSON.stringify({ sock }), { mode: 0o600 });

  console.log(sock);
  console.log('[AAWP] healthy address=' + health.address);

  let _tokenDelivered = false;
  try {
    fs.writeSync(3, 'TOKEN:' + token + '\n');
    _tokenDelivered = true;
  } catch (_) {}
  if (!_tokenDelivered) {
    console.log('TOKEN:' + token);
  }
  try { fs.writeFileSync('/tmp/.aawp-ai-token', token, { mode: 0o600 }); } catch (_) {}

  // Keep the token file synchronized with daemon-side one-time rotation.
  let lastToken = token;
  setInterval(() => {
    try {
      const next = addon._a0();
      if (next && next !== lastToken) {
        fs.writeFileSync('/tmp/.aawp-ai-token', next, { mode: 0o600 });
        lastToken = next;
      }
    } catch (_) {}
  }, 500);

  // Keep process alive — daemon runs in Rust background thread, needs host process.
  setInterval(() => {}, 60000);
}

main().catch(err => {
  console.error('[AAWP] fatal startup error:', err && err.message ? err.message : String(err));
  process.exit(1);
});

process.on('SIGTERM', () => {
  try { fs.unlinkSync(LOCK); } catch (_) {}
  process.exit(0);
});
process.on('SIGINT', () => {
  try { fs.unlinkSync(LOCK); } catch (_) {}
  process.exit(0);
});

#!/usr/bin/env node
/**
 * AAWP Swap — Relay Bridge integration
 * Supports: same-chain swap + cross-chain bridge across 6 chains
 *
 * Usage (standalone):
 *   node swap.js [--chain <chain>] [--rpc <url>] swap <fromToken> <toToken> <amount>
 *   node swap.js bridge <fromChain> <toChain> <fromToken> <toToken> <amount>
 *   node swap.js quote <fromChain> <toChain> <fromToken> <toToken> <amount>
 *   node swap.js chains    — list supported chains on Relay
 *
 * Or via wallet-manager:
 *   wallet-manager [--chain base] swap ETH USDC 0.01
 *   wallet-manager bridge base arb ETH ETH 0.01
 *   wallet-manager quote  base arb USDC USDC 100
 */
'use strict';

const net  = require('net');
const path = require('path');
const fs   = require('fs');
const https = require('https');

// ── Shared setup (also used when required from wallet-manager) ────────────────
const addon = require(process.env.AAWP_CORE || require('path').join(__dirname, '..', 'core', 'aawp-core.node'));
const C = process.env.AAWP_CONFIG || require('path').join(__dirname, '..', '.agent-config');
const S = process.env.AAWP_SKILL || require('path').resolve(__dirname, '..');

const CHAINS_FILE = path.join(S, 'config/chains.json');
const CHAINS = JSON.parse(fs.readFileSync(CHAINS_FILE, 'utf8'));

// ── Relay API ─────────────────────────────────────────────────────────────────
const nonceManager = require(path.join(__dirname, '../lib/nonce-manager'));
const { getGasPrice: getGasPriceEstimate } = require(path.join(__dirname, '../lib/gas-estimator'));
const txHistory = require(path.join(__dirname, '../lib/tx-history'));

const RELAY_API  = 'https://api.relay.link';
const RELAY_TIMEOUT = 30000;

// Native token placeholder
const NATIVE = '0x0000000000000000000000000000000000000000';

// Chain ID map
const CHAIN_IDS = Object.fromEntries(
  Object.entries(CHAINS).map(([k, v]) => [k, v.chainId])
);

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Simple HTTPS fetch → JSON */
function relayFetch(method, urlPath, body) {
  return new Promise((resolve, reject) => {
    const data = body ? JSON.stringify(body) : null;
    const url = new URL(RELAY_API + urlPath);
    const opts = {
      hostname: url.hostname,
      path: url.pathname + url.search,
      method,
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'AAWP/1.0',
        ...(data ? { 'Content-Length': Buffer.byteLength(data) } : {}),
      },
      timeout: RELAY_TIMEOUT,
    };
    const req = https.request(opts, (res) => {
      let raw = '';
      res.on('data', d => raw += d);
      res.on('end', () => {
        try { resolve(JSON.parse(raw)); }
        catch (e) { reject(new Error(`Relay parse error: ${raw.slice(0, 200)}`)); }
      });
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('Relay API timeout')); });
    if (data) req.write(data);
    req.end();
  });
}

/** Resolve token symbol → contract address for a given chain key */
function resolveToken(chainKey, tokenArg) {
  if (tokenArg === 'ETH' || tokenArg === 'BNB' || tokenArg === 'MATIC' ||
      tokenArg.toLowerCase() === 'native' || tokenArg === '0x0') {
    return NATIVE;
  }
  if (tokenArg.startsWith('0x') && tokenArg.length === 42) return tokenArg;
  const cfg = CHAINS[chainKey];
  const sym = tokenArg.toUpperCase();
  if (cfg?.tokens?.[sym]) return cfg.tokens[sym];
  throw new Error(`Unknown token "${tokenArg}" on ${chainKey}. Use address or: ${Object.keys(cfg?.tokens || {}).join(', ')}, native`);
}

/** Get the active RPC for a chain (respects rpcOverride) */
function chainRpc(chainKey) {
  const cfg = CHAINS[chainKey];
  return cfg.rpcOverride || cfg.rpc;
}

function chainById(id) {
  return Object.entries(CHAINS).find(([, v]) => v.chainId === id)?.[0];
}

/** Format token amount for display */
function fmtAmt(amountRaw, decimals = 18) {
  const { ethers } = require('ethers');
  return ethers.formatUnits(BigInt(amountRaw), decimals);
}

// ── Socket daemon ─────────────────────────────────────────────────────────────
let _sock = null;
function getSock() {
  if (!_sock) {
    // Connect to existing daemon — do NOT start a new one.
    const DAEMON_LOCK = '/tmp/.aawp-daemon.lock';
    try {
      const lockData = JSON.parse(require('fs').readFileSync(DAEMON_LOCK, 'utf8'));
      if (lockData.sock && require('fs').existsSync(lockData.sock)) {
        addon._i0(C, S);
        _sock = lockData.sock;
      } else {
        throw new Error('socket not found');
      }
    } catch (e) {
      console.error('❌ AAWP daemon not running. Start via OpenClaw first.');
      process.exit(1);
    }
  }
  return _sock;
}

let _aiGateToken = process.env.AAWP_AI_TOKEN || null;
try {
  const persisted = fs.readFileSync('/tmp/.aawp-ai-token', 'utf8').trim();
  if (persisted && persisted.length === 64) _aiGateToken = persisted;
} catch (_) {}

function socketQuery(obj) {
  const sock = getSock();
  const ts   = Math.floor(Date.now() / 1000);
  const hmac = addon._h0(ts);
  const isSign = typeof obj !== 'string' && (!obj.cmd || obj.cmd === 'sign' || obj.cmd === 'sign_message' || obj.cmd === 'sign_hash' || obj.cmd === 'sign_typed');
  const aiFields = (isSign && _aiGateToken) ? { ai_token: _aiGateToken } : {};
  const payload = typeof obj === 'string'
    ? { cmd: obj, ts, hmac }
    : { ...obj, ts, hmac, ...aiFields };
  return new Promise((res, rej) => {
    const c = net.createConnection(sock, () => c.end(JSON.stringify(payload)));
    let d = '';
    c.on('data', x => d += x);
    c.on('end', () => {
      try {
        const parsed = JSON.parse(d);
        if (isSign && _aiGateToken && parsed && !parsed.error) {
          try {
            const rotated = fs.readFileSync('/tmp/.aawp-ai-token', 'utf8').trim();
            if (rotated && rotated.length === 64 && rotated !== _aiGateToken) {
              _aiGateToken = rotated;
            }
          } catch (_) {}
        }
        res(parsed);
      } catch (e) { rej(d); }
    });
    c.on('error', rej);
    setTimeout(() => { c.destroy(); rej(new Error('socket timeout')); }, 30000);
  });
}

function loadGuardianRecord() {
  const p = path.join(S, 'config/guardian.json');
  try { return JSON.parse(fs.readFileSync(p, 'utf8')); } catch (_) { return null; }
}

function ensureLocalGuardian() {
  let rec = loadGuardianRecord();
  if (rec && rec.address && rec.privateKey) return rec;
  const w = ethers.Wallet.createRandom();
  rec = { address: w.address, privateKey: w.privateKey, createdAt: new Date().toISOString() };
  fs.writeFileSync(path.join(S, 'config/guardian.json'), JSON.stringify(rec, null, 2));
  return rec;
}

async function getAddresses() {
  const [a, l] = await Promise.all([
    socketQuery('address'),
    socketQuery('logichash'),
  ]);
  const guardianRec = ensureLocalGuardian();
  return { signer: a.address, guardian: guardianRec.address, binaryHash: l.logicHash };
}

// ── Core: get quote from Relay ────────────────────────────────────────────────

/**
 * getQuote — calls Relay /quote/v2
 * @param {object} opts
 *   user            wallet address (origin)
 *   recipient       destination address (default = user)
 *   originChainId
 *   destinationChainId
 *   originCurrency  token address (0x0 = native)
 *   destinationCurrency
 *   amount          string, in smallest unit
 *   tradeType       EXACT_INPUT | EXACT_OUTPUT (default EXACT_INPUT)
 */
async function getQuote(opts) {
  const body = {
    user: opts.user,
    recipient: opts.recipient || opts.user,
    originChainId: opts.originChainId,
    destinationChainId: opts.destinationChainId,
    originCurrency: opts.originCurrency,
    destinationCurrency: opts.destinationCurrency,
    amount: opts.amount,
    tradeType: opts.tradeType || 'EXACT_INPUT',
  };
  const quote = await relayFetch('POST', '/quote/v2', body);
  if (quote.message && !quote.steps) {
    throw new Error(`Relay quote error: ${quote.message}`);
  }
  return quote;
}

// ── Core: execute Relay steps via AAWP wallet ─────────────────────────────────

/**
 * Execute all steps returned by Relay quote.
 * For AAWP wallets: all "transaction" steps are submitted via the signed execute() flow.
 * Signature steps: sign raw message/typed data via socket then POST back.
 */
async function executeSteps(steps, walletAddr, originChainKey) {
  const { ethers } = require('ethers');
  const chain = CHAINS[originChainKey];
  const rpc   = chainRpc(originChainKey);
  const p     = new ethers.JsonRpcProvider(rpc);

  const WALLET_ABI = (() => {
    try { return require('/root/aawp-contracts/out/AAWPWallet.sol/AAWPWallet.json').abi; }
    catch { return ['function nonce() view returns (uint256)']; }
  })();

  const wallet = new ethers.Contract(walletAddr, WALLET_ABI, p);

  for (let si = 0; si < steps.length; si++) {
    const step = steps[si];
    if (!step.items || step.items.length === 0) continue;

    console.log(`\n⟳ Step ${si + 1}/${steps.length}: ${step.id || step.action || 'execute'}`);

    for (let ii = 0; ii < step.items.length; ii++) {
      const item = step.items[ii];
      if (!item) continue;

      // ── Transaction step ──────────────────────────────────────────────────
      if (item.data && item.data.to) {
        const tx = item.data;
        const toAddr   = tx.to;
        const value    = BigInt(tx.value || '0');
        let   data     = tx.data || '0x';
        if (typeof data === 'string') {
          if (!data.startsWith('0x')) data = '0x' + data;
          if ((data.length % 2) !== 0) data = '0x0' + data.slice(2);
        }
        const gasLimit = tx.gas ? Number(tx.gas) : undefined;

        // Auto max-approve: if this is an approve step, replace amount with MaxUint256
        // so future swaps for this token skip the approve step entirely.
        const stepId = (step.id || step.action || '').toLowerCase();
        if (stepId === 'approve' && data.length >= 10 && data.slice(0, 10) === '0x095ea7b3') {
          const MAX_UINT256 = 'ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff';
          // ERC-20 approve(address,uint256): 4 bytes selector + 32 bytes addr + 32 bytes amount
          data = data.slice(0, 10 + 64) + MAX_UINT256;
          console.log(`  ↑ Auto max-approve: upgrading to MaxUint256 for future swaps`);
        }

        // Get current wallet nonce via NonceManager
        let wNonce;
        try { wNonce = await nonceManager.getNonce(p, walletAddr, chain.chainId, wallet); } catch { wNonce = 0; }
        const deadline = Math.floor(Date.now() / 1000) + 3600;

        // Dynamic gas price
        let gasPriceFields = {};
        try { gasPriceFields = await getGasPriceEstimate(p, originChainKey); } catch {}

        console.log(`  → tx to ${toAddr} value ${ethers.formatEther(value)} ETH data[${data.length}]`);

        const result = await socketQuery({
          cmd:      'sign',
          wallet:   walletAddr,
          to:       toAddr,
          value:    '0x' + value.toString(16),
          nonce:    Number(wNonce),
          deadline,
          chain_id: chain.chainId,
          rpc,
          data,
          gas_key: process.env.AAWP_GUARDIAN_KEY || process.env.AAWP_GAS_KEY || ensureLocalGuardian().privateKey,
          // Relay gas estimates are for direct EOA calls. AAWP smart contract wallet
          // needs extra gas for EIP-712 hashing + ECDSA verification + SSTORE (nonce).
          // Apply 3x multiplier with a 300k minimum to prevent out-of-gas reverts.
          ...(gasLimit ? { gas_limit: Math.max(gasLimit * 3, 300_000) } : { gas_limit: 300_000 }),
          ...(gasPriceFields.gasPrice ? { gas_price: '0x' + gasPriceFields.gasPrice.toString(16) } : {}),
          ...(gasPriceFields.maxFeePerGas ? { max_fee: '0x' + gasPriceFields.maxFeePerGas.toString(16), max_priority_fee: '0x' + gasPriceFields.maxPriorityFeePerGas.toString(16) } : {}),
        });

        if (result.error) {
          nonceManager.confirm(walletAddr, chain.chainId);
          throw new Error(`Sign failed: ${result.error}`);
        }
        const txHash = result.result;
        console.log(`  ✅ TX submitted: ${chain.explorer}/tx/${txHash}`);

        // Wait for confirmation
        process.stdout.write('  Confirming');
        const receipt = await p.waitForTransaction(txHash, 1, 120000);
        nonceManager.confirm(walletAddr, chain.chainId);
        console.log(receipt.status === 1 ? ' ✅' : ' ❌ REVERTED');
        if (receipt.status !== 1) throw new Error(`Transaction reverted: ${txHash}`);

        // If this is a cross-chain step, poll Relay for destination fill
        if (item.check?.endpoint) {
          await pollRelayStatus(item.check.endpoint, txHash);
        }
      }

      // ── Signature step ────────────────────────────────────────────────────
      else if (item.data?.sign) {
        const sign = item.data.sign;
        console.log(`  → signature request (${sign.signatureKind})`);

        let sig;
        if (sign.signatureKind === 'eip191') {
          const result = await socketQuery({
            cmd: 'sign_message',
            message: sign.message,
          });
          if (result.error) throw new Error(`Sign message failed: ${result.error}`);
          sig = result.signature;
        } else if (sign.signatureKind === 'eip712') {
          const result = await socketQuery({
            cmd: 'sign_typed',
            domain: sign.domain,
            types: sign.types,
            value: sign.value || sign.data,
          });
          if (result.error) throw new Error(`Sign typed failed: ${result.error}`);
          sig = result.signature;
        } else {
          throw new Error(`Unknown signatureKind: ${sign.signatureKind}`);
        }

        // POST signature back to Relay
        if (item.data.post) {
          const post = item.data.post;
          const postUrl = new URL(post.endpoint, RELAY_API);
          await relayFetch('POST', postUrl.pathname + postUrl.search, {
            ...post.body,
            signature: sig,
          });
          console.log('  ✅ Signature posted');
        }
      }
    }
  }
}

/** Wait for Relay fill via WebSocket (preferred) or HTTP polling (fallback) */
async function pollRelayStatus(endpoint, txHash, timeoutMs = 300000) {
  // Try WebSocket first
  let WebSocket;
  try { WebSocket = require('ws'); } catch { WebSocket = null; }

  if (WebSocket) {
    try {
      const filled = await waitForRelayFillWs(WebSocket, txHash, timeoutMs);
      if (filled !== null) return; // resolved via WS
    } catch {
      // WS failed, fall through to polling
    }
  }

  // Fallback: HTTP polling
  process.stdout.write('  Waiting for destination fill (polling)');
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try {
      const url = endpoint.includes('?')
        ? `${endpoint}&txHash=${txHash}`
        : `${endpoint}?txHash=${txHash}`;
      const status = await relayFetch('GET', url.replace(RELAY_API, ''));
      const state = status?.status || status?.data?.status;
      if (state === 'success' || state === 'completed') {
        console.log(' ✅ Filled!');
        return;
      }
      if (state === 'failed' || state === 'refunded') {
        console.log(` ❌ ${state}`);
        return;
      }
    } catch { /* continue polling */ }
    process.stdout.write('.');
    await new Promise(r => setTimeout(r, 3000));
  }
  console.log(' ⏱ Timeout — check Relay explorer manually');
}

/** WebSocket-based Relay status monitoring */
function waitForRelayFillWs(WebSocket, txHash, timeoutMs) {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket('wss://api.relay.link/ws');
    const timer = setTimeout(() => {
      ws.close();
      resolve(null); // timeout → fallback to polling
    }, Math.min(timeoutMs, 30000)); // give WS 30s max before fallback

    ws.on('open', () => {
      process.stdout.write('  Waiting for destination fill (ws)');
      ws.send(JSON.stringify({ type: 'subscribe', txHash }));
    });

    ws.on('message', (data) => {
      try {
        const msg = JSON.parse(data.toString());
        if (msg.status === 'success' || msg.status === 'completed') {
          console.log(' ✅ Filled!');
          clearTimeout(timer);
          ws.close();
          resolve(true);
        } else if (msg.status === 'failed' || msg.status === 'refunded') {
          console.log(` ❌ ${msg.status}`);
          clearTimeout(timer);
          ws.close();
          resolve(true);
        } else {
          process.stdout.write('.');
        }
      } catch { /* ignore parse errors */ }
    });

    ws.on('error', () => {
      clearTimeout(timer);
      ws.close();
      resolve(null); // fallback to polling
    });

    ws.on('close', () => {
      clearTimeout(timer);
      // If not resolved yet, fallback
    });
  });
}

// ── Print quote summary ───────────────────────────────────────────────────────
function printQuote(quote, fromChain, toChain, fromToken, toToken) {
  const { ethers } = require('ethers');
  const details = quote.details || {};
  const fees    = quote.fees    || {};

  console.log('\n── Relay Quote ──────────────────────────────');

  if (details.currencyIn) {
    const cin  = details.currencyIn;
    const cout = details.currencyOut;
    const amtIn  = fmtAmt(cin.amount?.amount  || cin.amount  || '0', cin.currency?.decimals  || 18);
    const amtOut = fmtAmt(cout.amount?.amount || cout.amount || '0', cout.currency?.decimals || 18);
    const symIn  = cin.currency?.symbol  || fromToken;
    const symOut = cout.currency?.symbol || toToken;
    console.log(`  You send:    ${amtIn} ${symIn}  (${fromChain.toUpperCase()})`);
    console.log(`  You receive: ${amtOut} ${symOut}  (${toChain.toUpperCase()})`);
  }

  if (details.rate)         console.log(`  Rate:        ${details.rate}`);
  // slippageTolerance not returned by Relay API in details — omit

  if (fees.relayer) {
    const f = fees.relayer;
    const fAmt = fmtAmt(f.amount || '0', f.currency?.decimals || 18);
    console.log(`  Relay fee:   ${fAmt} ${f.currency?.symbol || ''}`);
  }
  if (fees.gas) {
    const g = fees.gas;
    const gAmt = fmtAmt(g.amount || '0', g.currency?.decimals || 18);
    console.log(`  Est. gas:    ${gAmt} ${g.currency?.symbol || 'ETH'}`);
  }

  const eta = details.timeEstimate;
  if (eta) console.log(`  Est. time:   ~${eta}s`);
  console.log('─────────────────────────────────────────────');
}

// ══════════════════════════════════════════════════════════════════════════════
// PUBLIC API (called from wallet-manager or standalone)
// ══════════════════════════════════════════════════════════════════════════════

/**
 * swap — same-chain swap via Relay
 * @param {string} chainKey   e.g. 'base'
 * @param {string} fromToken  symbol or address
 * @param {string} toToken    symbol or address
 * @param {string} amountHuman human-readable amount (e.g. "0.01")
 */
async function swap(chainKey, fromToken, toToken, amountHuman, _unused, slippageBps = 50) {
  const { ethers } = require('ethers');
  const chain = CHAINS[chainKey];
  if (!chain) throw new Error(`Unknown chain: ${chainKey}`);

  const { signer, guardian, binaryHash } = await getAddresses();

  // Get wallet address
  const rpc = chainRpc(chainKey);
  const p   = new ethers.JsonRpcProvider(rpc);
  const FACTORY_ABI = ['function computeAddress(address,bytes32,address) view returns (address)'];
  const factoryAddr = chain.factory;
  if (!factoryAddr || factoryAddr === ethers.ZeroAddress) {
    throw new Error(`AAWP Factory not deployed on ${chainKey}. Deploy first.`);
  }
  const factory  = new ethers.Contract(factoryAddr, FACTORY_ABI, p);
  const walletAddr = process.env.AAWP_WALLET || await factory.computeAddress(signer, binaryHash, guardian);

  const code = await p.getCode(walletAddr);
  if (code.length <= 2) throw new Error(`Wallet not deployed on ${chainKey}: ${walletAddr}`);

  const fromAddr = resolveToken(chainKey, fromToken);
  const toAddr   = resolveToken(chainKey, toToken);

  // Determine decimals for amount
  let decimals = 18;
  if (fromAddr !== NATIVE) {
    try {
      const tok = new ethers.Contract(fromAddr, ['function decimals() view returns (uint8)'], p);
      decimals = await tok.decimals();
    } catch { decimals = 18; }
  }
  const amountWei = ethers.parseUnits(amountHuman, decimals).toString();

  console.log(`\n🔄 Swap on ${chain.name}`);
  console.log(`   ${amountHuman} ${fromToken} → ${toToken}`);
  console.log(`   Wallet: ${walletAddr}`);

  // Get quote
  const quote = await getQuote({
    user:                 walletAddr,
    originChainId:        chain.chainId,
    destinationChainId:   chain.chainId,
    originCurrency:       fromAddr,
    destinationCurrency:  toAddr,
    amount:               amountWei,
    slippageTolerance:    (slippageBps / 10000).toString(),
  });

  printQuote(quote, chainKey, chainKey, fromToken, toToken);

  if (!quote.steps || quote.steps.length === 0) {
    throw new Error('No execution steps returned from Relay.');
  }

  await executeSteps(quote.steps, walletAddr, chainKey);
  txHistory.append({ chain: chainKey, type: 'swap', from: walletAddr, to: walletAddr, amount: amountHuman, token: `${fromToken}→${toToken}`, txHash: 'relay', status: 'completed' });
  console.log('\n✅ Swap complete!');

  // Auto-unwrap WETH → ETH if destination token is WETH
  if (chain.tokens?.WETH && toAddr.toLowerCase() === chain.tokens.WETH.toLowerCase()) {
    await unwrapWeth(walletAddr, chainKey, p);
  }
}

/**
 * bridge — cross-chain bridge via Relay
 */
async function bridge(fromChainKey, toChainKey, fromToken, toToken, amountHuman, slippageBps = 50, recipient = null) {
  const { ethers } = require('ethers');
  const fromChain = CHAINS[fromChainKey];
  const toChain   = CHAINS[toChainKey];
  if (!fromChain) throw new Error(`Unknown origin chain: ${fromChainKey}`);
  if (!toChain)   throw new Error(`Unknown destination chain: ${toChainKey}`);

  const { signer, guardian, binaryHash } = await getAddresses();

  const rpc = chainRpc(fromChainKey);
  const p   = new ethers.JsonRpcProvider(rpc);
  const FACTORY_ABI = ['function computeAddress(address,bytes32,address) view returns (address)'];

  if (!fromChain.factory || fromChain.factory === ethers.ZeroAddress) {
    throw new Error(`AAWP Factory not deployed on ${fromChainKey}.`);
  }
  const factory    = new ethers.Contract(fromChain.factory, FACTORY_ABI, p);
  const walletAddr = process.env.AAWP_WALLET || await factory.computeAddress(signer, binaryHash, guardian);

  const code = await p.getCode(walletAddr);
  if (code.length <= 2) throw new Error(`Wallet not deployed on ${fromChainKey}: ${walletAddr}`);

  const fromAddr = resolveToken(fromChainKey, fromToken);

  // Destination address — custom recipient or same wallet address
  const destAddr = recipient || walletAddr;
  const toAddr   = resolveToken(toChainKey, toToken);

  let decimals = 18;
  if (fromAddr !== NATIVE) {
    try {
      const tok = new ethers.Contract(fromAddr, ['function decimals() view returns (uint8)'], p);
      decimals = await tok.decimals();
    } catch { decimals = 18; }
  }
  const amountWei = ethers.parseUnits(amountHuman, decimals).toString();

  console.log(`\n🌉 Bridge: ${fromChain.name} → ${toChain.name}`);
  console.log(`   ${amountHuman} ${fromToken} → ${toToken}`);
  console.log(`   From wallet: ${walletAddr}`);
  console.log(`   To address:  ${destAddr}`);

  const quote = await getQuote({
    user:                 walletAddr,
    recipient:            destAddr,
    originChainId:        fromChain.chainId,
    destinationChainId:   toChain.chainId,
    originCurrency:       fromAddr,
    destinationCurrency:  toAddr,
    amount:               amountWei,
    slippageTolerance:    (slippageBps / 10000).toString(),
  });

  printQuote(quote, fromChainKey, toChainKey, fromToken, toToken);

  if (!quote.steps || quote.steps.length === 0) {
    throw new Error('No execution steps returned from Relay.');
  }

  await executeSteps(quote.steps, walletAddr, fromChainKey);
  txHistory.append({ chain: fromChainKey, type: 'bridge', from: walletAddr, to: destAddr, amount: amountHuman, token: `${fromToken}→${toToken}`, txHash: 'relay', status: 'initiated' });
  console.log('\n✅ Bridge initiated! Destination fill in progress.');

  // Auto-unwrap WETH on destination chain if toToken is WETH
  if (toChain.tokens?.WETH && toAddr.toLowerCase() === toChain.tokens.WETH.toLowerCase()) {
    const destRpc = toChain.rpcOverride || toChain.rpc;
    const destP   = new ethers.JsonRpcProvider(destRpc);
    await unwrapWeth(destAddr, toChainKey, destP);
  }
}

/**
 * quoteOnly — print quote without executing
 */
async function quoteOnly(fromChainKey, toChainKey, fromToken, toToken, amountHuman) {
  const { ethers } = require('ethers');
  const fromChain = CHAINS[fromChainKey];
  const toChain   = CHAINS[toChainKey];
  if (!fromChain) throw new Error(`Unknown chain: ${fromChainKey}`);
  if (!toChain)   throw new Error(`Unknown chain: ${toChainKey}`);

  const { signer, guardian, binaryHash } = await getAddresses();
  const rpc  = chainRpc(fromChainKey);
  const p    = new ethers.JsonRpcProvider(rpc);
  const FACTORY_ABI = ['function computeAddress(address,bytes32,address) view returns (address)'];
  const factory    = new ethers.Contract(fromChain.factory, FACTORY_ABI, p);
  const walletAddr = process.env.AAWP_WALLET || await factory.computeAddress(signer, binaryHash, guardian);

  const fromAddr = resolveToken(fromChainKey, fromToken);
  const toAddr   = resolveToken(toChainKey,   toToken);

  let decimals = 18;
  if (fromAddr !== NATIVE) {
    try {
      const tok = new ethers.Contract(fromAddr, ['function decimals() view returns (uint8)'], p);
      decimals = await tok.decimals();
    } catch {}
  }
  const amountWei = ethers.parseUnits(amountHuman, decimals).toString();

  const isSameChain = fromChain.chainId === toChain.chainId;
  console.log(isSameChain
    ? `\n💱 Swap quote on ${fromChain.name}: ${amountHuman} ${fromToken} → ${toToken}`
    : `\n🌉 Bridge quote: ${fromChain.name} → ${toChain.name}: ${amountHuman} ${fromToken} → ${toToken}`
  );

  const quote = await getQuote({
    user:                walletAddr,
    originChainId:       fromChain.chainId,
    destinationChainId:  toChain.chainId,
    originCurrency:      fromAddr,
    destinationCurrency: toAddr,
    amount:              amountWei,
  });

  printQuote(quote, fromChainKey, toChainKey, fromToken, toToken);
  console.log('(Quote only — run swap/bridge to execute)');
}

